import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';
import { readFileSync } from 'node:fs';

const read = (p) => JSON.parse(readFileSync(new URL(p, import.meta.url), 'utf8'));
const domains = read('./src/config/domains.json');
// Same-site redirects generated by scripts/build-redirects.mjs. On Cloudflare
// Pages the real 301s come from public/_redirects; these emit HTML redirect
// pages so the same URLs also work on hosts that ignore _redirects
// (e.g. the GitHub Pages audit copy at as.nur.city).
const generated = read('./src/data/static-redirects.json');

// Pages that should never be in the sitemap (utility / preview / card-support pages).
const SKIP = [/\/checkout-preview\//, /\/free\/(confirmed|starter-pack)-preview\//, /\/free\/check-your-email\//, /\/qr\//, /\/support\//, /\/start\//, /\/404/];

export default defineConfig({
  site: domains.production ? domains.apex : 'https://as.nur.city',
  trailingSlash: 'always',
  integrations: domains.production ? [sitemap({ filter: (page) => !SKIP.some((re) => re.test(page)) })] : [],
  redirects: {
    // v10: /club/ and /parents/ were renamed per src/config/routes.ts
    '/club/': '/adventure-club/',
    '/parents/': '/for-parents/',
    ...generated
  }
});
